// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2018, "4-5", [{"author":"О. Подлесская","question":"Найдите лишнее по смыслу слово в этом ряду.","choices":["<em>большой</em>","<em>указательный</em>","<em>средний</em>","<em>безымянный</em>","<em>последний</em>."],"key":"Д","review":["Ряд слов по смыслу","Подставь слово «палец» к каждому варианту. Получатся названия четырёх пальцев — большой, указательный, средний и безымянный.","Пятый палец называется мизинцем. Слово «последний» указывает лишь на порядок, поэтому не входит в ряд названий."]},{"author":"Е. Бикмаев","question":"Женя прочитал, что рубашки делают из льна. Как называется этот материал в именительном падеже?","choices":["льно","лёно","лено́","лён","лень"],"key":"Г","review":["Из чего сделана рубашка","В сочетании «из льна» материал отвечает на вопрос «из чего?». Для начальной формы предлог нужно убрать и ответить на вопрос «что?».","Сырьё для ткани — лён. Сравни «Лён растёт на поле» и «Рубашку сшили из льна»."]},{"author":"Б. Иомдин","question":"В каком предложении можно заменить <em>всякий</em> на <em>каждый</em>?","choices":["<em>Болтали о всякой всячине</em>.","<em>На всякий случай позвони</em>.","<em>Ходят тут всякие.</em>","<em>Всякий раз удивляюсь</em>.","<em>Смотрел без всякого интереса</em>."],"key":"Г","review":["Замена слова «всякий»","Проверь смысл четырёх выражений. «Всякая всячина» говорит о разных вещах, «на всякий случай» — о подстраховке, «ходят тут всякие» — о каких-то людях, «без всякого интереса» — об отсутствии интереса.","Только «всякий раз» означает «каждый раз». Скажи «Каждый раз удивляюсь», и смысл фразы не изменится."]},{"author":"Е. Бикмаев","question":"Их у человека больше двух. Что это?","choices":["ресницы","брови","глаза","уши","щёки."],"key":"А","review":["Подсчёт частей тела","Представь лицо человека. На нём обычно два глаза, две брови и две щёки. По бокам головы два уха.","Ресницы растут вдоль каждого века, и на одном веке их уже больше двух. Значит, подходит «ресницы»."]},{"author":"Б. Иомдин и Ю. Халеева","question":"В каком примере пропущено не <em>здравия желаю</em>, а <em>желаю здоровья</em>?","choices":["<em>Митька козырнул: — _______!</em> (В. Белов)","<em>Крепко жму руку и _______</em>. (С. Маршак)","<em>_______, товарищ генерал.</em> (И. Грекова)","<em>Фельдфебель говорит «_______»</em>. (М. Лермонтов)","<em>Когда проходит отец, он вскакивает и кричит по-солдатски — _______!</em> (И. Шмелев)"],"key":"Б","review":["Два пожелания здоровья","Поищи признаки воинского приветствия. Козыряние, обращение к генералу, упоминание фельдфебеля и слова «по-солдатски» подсказывают выражение «здравия желаю».","В строке Маршака после «крепко жму руку и» естественно продолжить «желаю здоровья». Это обычное пожелание человеку."]},{"author":"Л. Фёдорова","question":"Какую букву <strong>нельзя</strong> вставить в запись <em>п_лить</em>, чтобы получилось слово?","choices":["<em>а</em>","<em>о</em>","<em>и</em>","<em>ы</em>","<em>е</em>."],"key":"Д","review":["Гласная для глагола","Попробуй вставить «а», «о», «и» и «ы». Можно палить из пушки, полить цветы, пилить доску и пылить сапогами на сухой дороге.","С буквой «е» получилось бы «пелить». Такого глагола в современном литературном языке нет, поэтому «е» не подходит."]},{"author":"Б. Иомдин","question":"Какого слова <strong>не</strong> существует?","choices":["<em>лгун</em>","<em>лжец</em>","<em>врун</em>","<em>врец</em>","<em>враль</em>."],"key":"Г","review":["Слова об обманщике","Собери слова в группы. От «лгать» получаются «лгун» и «лжец», а с «врать» связаны «врун» и «враль».","Кто-то мог придумать «врец» по образцу слова «лжец». В обычной речи человека, который врёт, называют «врун» или «враль»."]},{"author":"О. Подлесская","question":"В названии насекомого <em>стрекоза</em> скрывается название животного — <em>коза</em>. В каком слове <strong>не</strong> скрывается ещё одно живое существо?","choices":["<em>жаворонок</em>","<em>буйвол</em>","<em>утконос</em>","<em>таракан</em>","<em>дикобраз</em>."],"key":"В","review":["Спрятанное живое существо","Ищи подряд идущие буквы, как в «стрекозе». В «жаворонке» есть «ворон», в «буйволе» — «вол», в «таракане» — «рак», в «дикобразе» — «кобра».","В «утконосе» легко узнать часть «утко-», но слово «утка» целиком здесь не написано. Другое название живого существа тоже не спрятано, поэтому подходит «утконос»."]},{"author":"Е. Муравенко","question":"В каком слове в современном языке <strong>не</strong> выделяется суффикс?","choices":["<em>лавка</em>","<em>книжка</em>","<em>тетрадка</em>","<em>дверка</em>","<em>печка</em>."],"key":"А","review":["Суффиксы в словах","Найди исходные слова. «Книжка» образована от «книга», «тетрадка» — от «тетрадь», «дверка» — от «дверь», «печка» — от «печь». Во всех этих словах добавилась часть «-к-».","В современном разборе слова «лавка» весь кусочек «лавк-» относится к корню. Старое слово «лава», от которого произошло это название скамьи, сегодня в этом значении почти не употребляют."]},{"author":"С. Сай","question":"<em>Строители клали фундамент и готовили б_ _он</em>.\n<em>Я подхватила б_ _он с молоком и вышла из магазина</em>.\nВ этих двух предложениях пропущены по две буквы. Как надо заполнить пропуски?","choices":["<em>е</em>, <em>т</em>, <em>е</em>, <em>д</em>","<em>е</em>, <em>т</em>, <em>е</em>, <em>т</em>","<em>е</em>, <em>т</em>, <em>и</em>, <em>д</em>","<em>е</em>, <em>т</em>, <em>и</em>, <em>т</em>","<em>и</em>, <em>т</em>, <em>е</em>, <em>д</em>."],"key":"В","review":["Фундамент и молоко","Для фундамента используют строительную смесь — бетон. В первом пропуске это слово требует букв «е» и «т».","Молоко можно налить в бидон. Во втором слове нужно вставить «и» и «д». Вместе буквы идут в таком порядке — «е», «т», «и», «д»."]},{"author":"Е. Бикмаев","question":"Название какого числа, по одной из версий, происходит от древнерусского слова, означавшего ‘связка собольих шкур’?","choices":["20","30","40","50","60."],"key":"В","review":["Число и собольи шкурки","Сравни названия чисел из списка. В словах «двадцать», «тридцать», «пятьдесят» и «шестьдесят» можно узнать названия двух, трёх, пяти и шести десятков.","Слово «сорок» выделяется. По одной из версий, так называли связку из сорока собольих шкурок, и название перешло на число."]},{"author":"И. Иткин","question":"Настоящая фамилия этого писателя — Гриневский. А нам он известен как...","choices":["Фёдор Достоевский","Александр Грибоедов","Аполлон Григорьев","Александр Грин","Геннадий Гор."],"key":"Г","review":["Фамилия под псевдонимом","Сравни «Гриневский» с фамилиями в ответах. Если убрать последние буквы «евский», получится «Грин».","Так и называл себя в литературе Александр Степанович Гриневский. На обложках его книг пишут «Александр Грин»."]},{"author":"А. Пиперски","question":"В исконно русских словах, т. е. не заимствованных из других языков, встречается сочетание букв … .","choices":["<em>чя</em>","<em>чю</em>","<em>чы</em>","<em>чэ</em>","<em>чо</em>."],"key":"Д","review":["Какие буквы идут за «ч»","Вспомни написание «чай», «чудо», «чиж» и «чернила». За мягким [ч’] в исконных словах пишут «а», «у», «и», «е», а варианты с «я», «ю», «ы», «э» не подходят.","Сочетание «чо» встречается в таких словах, как «бочонок» и «волчок». Этого достаточно, чтобы выбрать его из списка."]},{"author":"Е. Бикмаев","question":"<em>Четыре чёрненьких чумазеньких чертёнка чертили чёрными чернилами чертёж.</em> Расставим слова этой скороговорки в алфавитном порядке. Какое слово окажется пятым? (Здесь <em>е</em> и <em>ё</em> считаются разными буквами.)","choices":["<em>четыре</em>","<em>чёрненьких</em>","<em>чертёнка</em>","<em>чертили</em>","<em>чернилами</em>."],"key":"А","review":["Скороговорка по алфавиту","Все слова начинаются на «ч», поэтому сравни вторые буквы. В алфавите идут «е», затем «ё», затем «у». Слова на «че» надо выписать первыми.","На «че» их ровно пять. Сначала идут «чернилами», «чертёж», «чертёнка» и «чертили», потому что «р» раньше «т». Пятым будет «четыре»."]},{"author":"Б. Иомдин и Ю. Халеева","question":"После встречи мы остались … с другом. Какое наречие означает, что мы были вдвоём и рядом больше никого не было?","choices":["в одиночестве","один","один-одинёшенек","наедине","накануне"],"key":"Г","unrated":false,"reviewedEdition":true,"review":["Как закончить предложение","«Один» и «один-одинёшенек» изменяются по родам и числам. «В одиночестве» — существительное с предлогом.","Неизменяемое наречие «наедине» подходит во фразу «остались наедине с другом». Здесь оно означает «вдвоём, без посторонних»."]},{"author":"Б. Иомдин","question":"Вот четверостишие Юлиана Тувима в переводе Сергея Михалкова:\nТритесь губкой и мочалкой!\nПотерпите — не беда!\nИ чернила, и варенье\nСмоет мыло и вода.\nСколько в нём слов в именительном падеже?","choices":["два","три","четыре","пять","семь."],"key":"Б","review":["Падежи в четверостишии","Найди, что смоет пятна. Это «мыло и вода», оба слова в именительном падеже. «Чернила» и «варенье» отвечают на вопрос «смоет что?» и здесь стоят в винительном падеже.","В выражении «не беда» слово «беда» тоже в именительном падеже. «Губкой» и «мочалкой» отвечают на вопрос «чем?», поэтому их не считаем. Всего три слова."]},{"author":"Л. Фёдорова","question":"Чешский и русский — родственные языки. Что означают чешские слова: letenka, letec, letiště, letadlo? (Читаются как летенка, летец, летиште, летадло.)","choices":["билет на самолёт, аэропорт, самолёт, лётчик","самолёт, лётчик, билет на самолёт, аэропорт","аэропорт, билет на самолёт, лётчик, самолёт","билет на самолёт, лётчик, аэропорт, самолёт","самолёт, аэропорт, билет на самолёт, лётчик."],"key":"Г","review":["Чешские слова о полёте","Сравни чешские слова с русскими. В «letec» слышится слово о человеке, который летает, то есть о лётчике. «Letiště» напоминает название места на «-ище», где самолёты взлетают, — аэропорта.","Остаются «letenka» для билета на самолёт и «letadlo» для самого самолёта. В порядке из условия получается «билет на самолёт, лётчик, аэропорт, самолёт»."]},{"author":"Б. Иомдин и Ю. Халеева","question":"Четыре примера встретились нам в начале предложений, а один — в середине предложения. Какой?","choices":["Доктор Пилюлькин","Робинзон Крузо","Капитан Врунгель","Граф Монте-Кристо","Королева Марго."],"key":"Б","review":["Большая буква у героев","Проверь, какое слово перед именем служит названием профессии или титула. «Доктор», «капитан», «граф» и «королева» в середине предложения обычно пишутся со строчной буквы.","«Робинзон» — имя, оно начинается с заглавной буквы в любой позиции. Поэтому «Робинзон Крузо» мог встретиться в середине предложения."]},{"author":"Е. Муравенко","question":"Вот двустишия из книжки А. Шибаева о буквах и словах:\nНа пожелтевшую траву\nРоняет лев свою листву.\n\nСели в ложку — и айда!\nПо реке туда-сюда…\nВ два слова вместо правильных согласных забрались другие. Найдите эти слова, замените в них неправильные согласные правильными и выберите слово с этими правильными согласными.","choices":["<em>сажа</em>","<em>вода</em>","<em>соль</em>","<em>вол</em>","<em>сад</em>."],"key":"Д","review":["Перепутанные согласные","Проверь, кто роняет листву и в чём едут по реке. Вместо «лев» нужно «лес», вместо «ложку» — «лодку».","После исправлений появились буквы «с» и «д». Обе входят в слово «сад»."]},{"author":"Л. Фёдорова","question":"В журнале «Мурзилка» за 2002 г. читаем:\n<em>Хозяйничают здесь, кроме Деда Мороза и матушки Зимы, девицы-красавицы</em> <...>. <em>Кто в сувенирной лавке гостям улыбается, кто волшебную перину в</em> <em>Дедушкиной опочивальне взбивает</em>. А что такое опочивальня?","choices":["гостиная","столовая","спальня","ванная","кладовая."],"key":"В","review":["Комната Деда Мороза","Спроси, зачем взбивают перину. Это мягкая постель, которую так готовят ко сну.","Старинное «опочивать» значит «спать» или «отдыхать». Опочивальня — комната, где спят, то есть спальня."]},{"author":"И. Иткин","question":"Даны названия некоторых букв итальянского алфавита: <strong><em>d</em></strong> — <em>di</em>, <strong><em>m</em></strong> — <em>emme</em>, <strong><em>r</em></strong> — <em>erre</em>, <strong><em>p</em></strong> — <em>pi</em>. Как по-итальянски называются буквы <strong><em>b</em></strong>, <strong><em>n</em></strong>, <strong><em>t</em></strong>?","choices":["<em>bi</em>, <em>ni</em>, <em>ti</em>","<em>bi</em>, <em>enne</em>, <em>ette</em>","<em>bi</em>, <em>enne</em>, <em>ti</em>","<em>ebbe</em>, <em>ni</em>, <em>ette</em>","<em>ebbe</em>, <em>enne</em>, <em>ette</em>."],"key":"В","review":["Итальянские имена букв","В примерах «di» и «pi» к согласному прибавляется «i». Звуки [б] и [т] тоже произносятся коротко, как [д] и [п], поэтому им подходят «bi» и «ti».","Звук [н] можно протянуть, как [м] и [р]. Название «enne» устроено по тому же образцу, что «emme» и «erre». В итоге получаются «bi, enne, ti»."]},{"author":"Е. Бикмаев","question":"Джон разделил глаголы, оканчивающиеся на -<em>сти</em>, на четыре группы:\n1) <em>грести</em>, <em>скрести</em>; 2) <em>брести</em>, <em>вести</em>; 3) <em>трясти</em>, <em>нести</em>; 4) <em>плести</em>, <em>мести</em>. Над каждой группой он поставил для удобства букву. Перечислите эти буквы в порядке следования групп.","choices":["<em>б, д, т, с</em>","<em>б, д, с, т</em>","<em>л, д, с, т</em>","<em>л, ш, с, щ</em>","<em>л, ш, с, т.</em>"],"key":"Б","review":["Буквы над группами","Скажи про себя «я гребу», «я скребу», «я бреду», «я веду». Перед «-у» в первой группе появляется «б», во второй — «д».","Продолжи «я трясу», «я несу», «я плету», «я мету». Теперь перед «-у» стоят «с» и «т». Буквы всех групп идут в порядке «б, д, с, т»."]},{"author":"А. Пиперски","question":"Даны пары слов: <em>взор</em> — <em>гипс</em>, <em>нос</em> — <em>опт</em>, <em>юг</em> — <em>яд</em>. Какую ещё пару можно включить в этот список?","choices":["<em>стук</em> — <em>куст</em>","<em>пар</em> — <em>рот</em>","<em>волна</em> — <em>грива</em>","<em>пора</em> — <em>араб</em>","<em>юла</em> — <em>ямб</em>."],"key":"Д","review":["Буквы в парах слов","Проверь буквы на одинаковых местах. В «нос — опт» каждая буква второго слова идёт сразу за соответствующей буквой первого в алфавите. То же правило работает для «взор — гипс» и «юг — яд».","Замени буквы слова «юла» на следующие по алфавиту. После «ю» идёт «я», после «л» — «м», после «а» — «б». Получается «ямб»."]},{"author":"П. Аркадьев","question":"Многие глаголы в прошедшем времени заканчиваются на -<em>лал</em>, -<em>мал</em>, -<em>нал</em> и -<em>рал</em>, напр.: <em>клал</em>, <em>ломал</em>, <em>знал</em>, <em>убирал</em>. А вот из сочетаний -<em>лол</em>, <em>-мол</em>, <em>-нол</em> и <em>-рол</em> глаголы в прошедшем времени могут заканчиваться только на два. На какие?","choices":["на -<em>лол</em> и -<em>мол</em>","на -<em>лол</em> и -<em>нол</em>","на -<em>лол</em> и -<em>рол</em>","на -<em>мол</em> и -<em>рол</em>","на -<em>нол</em> и -<em>рол</em>. 4–5классы"],"key":"В","review":["Концы глаголов","Назови действия в прошедшем времени. «Колол» от «колоть» даёт «-лол», а «порол» от «пороть» или «спорол» от «спороть» дают «-рол».","Формы «молол» и «гнул» могут сбить с толку. У «молол» конец тоже «-лол», а «гнул» заканчивается на «-нул». Из данных сочетаний подходят «-лол» и «-рол»."]},{"author":"И. Иткин","question":"В стихотворении Владимира Маяковского «Хорошее отношение к лошадям» есть строка: «— Гриб. Грабь. Гроб. Груб». Сколько различающихся звуков между первым и вторым, вторым и третьим, третьим и четвёртым словом в этой строке?","choices":["4, 2, 1","3, 2, 1","2, 2, 2","2, 1, 2","2, 1, 1."],"key":"Б","review":["Звуки у Маяковского","Сравни на слух «гриб» и «грабь». В первом слове [р’], [и], [п], во втором — [р], [а], [п’]. Первый звук [г] общий, остальные три различаются.","У «грабь» и «гроб» меняются гласный и мягкость последнего согласного. У «гроб» и «груб» меняется только гласный. Получается 3, 2, 1."]},{"author":"Б. Иомдин","question":"На уроке русского языка третьеклассники изучали существительные и играли в игру. Каждый должен был показать предмет по определённым правилам. Коля показал карандаш, Таня — тетрадку, Света — сумку, Петя — пенал. А что показал Руслан?","choices":["ручку","фломастер","рюкзак","расписание","клей."],"key":"В","review":["Вещи для школьной игры","Сравни имя каждого ученика с названием показанной вещи. Начальные буквы одинаковы, поэтому для Руслана нужно слово на «р».","Есть ещё правило о роде. У Коли и Пети предметы мужского рода, у Тани и Светы — женского. Из вариантов на «р» мужского рода только «рюкзак»."]},{"author":"И. Иткин","question":"В повести Василия Аксёнова «Мой дедушка — памятник» советский корабль заходит в порт вымышленного острова Эмпирей. Местные жители встречают его словами: <em>Вилькамес совьет легопикор бу легопикор Эмпирея!</em> Что означает эта фраза?","choices":["Моряки Эмпирея желают советским морякам счастливого плавания!","Слава советским людям — друзьям острова Эмпирей!","Великие советские моряки, добро пожаловать в Эмпирей!","Привет советским футболистам от футболистов Эмпирея!","Поздравляем советский корабль от имени жителей Эмпирея!"],"key":"Г","review":["Приветствие на Эмпирее","Присмотрись к знакомым частям фразы. «Совьет» напоминает слово «советский», «Эмпирея» называет остров, а слово «легопикор» повторяется дважды.","«Легопикор» повторяется до слова «Эмпирея», которое стоит в самом конце. В варианте о моряках название острова звучит почти сразу. Фраза «Привет советским футболистам от футболистов Эмпирея!» сохраняет и повтор, и порядок."]},{"author":"Б. Иомдин","question":"Сидел у реки… Закончите эту фразу так, чтобы у неё появилось интересное свойство.","choices":["<em>и ждал лодочника</em>","<em>и ел редиску</em>","<em>и размышлял о динозаврах</em>","<em>и ловил рыбу</em>","<em>и слушал джаз</em>."],"key":"Б","review":["Фраза у реки","Запиши «сидел у реки» без пробелов и переставь буквы по алфавиту. Получится набор «д, е, е, и, и, к, л, р, с, у».","Из того же набора можно составить «и ел редиску». У двух половин целой фразы одинаковые буквы, причём каждая встречается одинаковое число раз."]},{"author":"А. Леонтьева","question":"На средневековых изображениях святой Агнессы, как правило, можно увидеть также детёныша домашнего животного. Какого?","choices":["овцы","козы","коровы","ослицы","собаки."],"key":"А","review":["Агнесса на изображениях","Сравни имя «Агнесса» со старым словом «агнец». Так называли ягнёнка, и похожее латинское слово «agnus» тоже означает ягнёнка.","Ягнёнок стал одним из знаков, по которым на картинах узнают святую Агнессу. Ягнёнок — детёныш овцы."]},{"author":"Б. Иомдин","question":"Пьер учит русский язык и выписывает слова в два столбика:\nжук │ рак\nбык │ зуб\nгриб │ внук\n… │ …\nКуда он выпишет слова кит, плот, знак?","choices":["<em>кит</em> — в левый столбик, <em>плот</em> и <em>знак</em> — в правый столбик","<em>кит</em> и <em>плот</em> — в левый столбик, <em>знак</em> — в правый столбик","<em>плот</em> — в левый столбик, <em>кит</em> и <em>знак</em> — в правый столбик","<em>знак</em> — в левый столбик, <em>кит</em> и <em>плот</em> — в правый столбик","<em>плот</em> и <em>знак</em> — в левый столбик, <em>кит</em> — в правый столбик."],"key":"Б","review":["Два столбика Пьера","Поставь слова во множественное число. Слева ударение переходит на окончание — «жуки́», «быки́», «грибы́». Справа остаётся в корне — «ра́ки», «зу́бы», «вну́ки».","Проверь оставшиеся слова. В «киты́» и «плоты́» ударение на окончании, поэтому они идут влево. В «зна́ки» оно осталось в корне, поэтому слово идёт вправо."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
